fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn save(p:impl AsRef<Path>,v:Value){assert!(!p.as_ref().exists());fs::write(p,serde_json::to_vec_pretty(&v).unwrap()).unwrap()}
fn files(p:&Path,base:&Path,out:&mut BTreeMap<String,String>){if p.is_dir(){for e in fs::read_dir(p).unwrap(){files(&e.unwrap().path(),base,out)}}else{out.insert(p.strip_prefix(base).unwrap().display().to_string(),hash(p));}}
fn archive(root:&str,name:&str,members:&[&str])->Value{
 let out=format!("{D}/artifacts/{name}.tar.gz");let mut original=BTreeMap::new();
 for member in members{files(&Path::new(root).join(member),Path::new(root),&mut original);}
 assert!(Command::new("tar").args(["-czf",&out,"-C",root]).args(members).status().unwrap().success());
 let extracted=format!("{R}/roundtrip-{name}");fs::create_dir(&extracted).unwrap();
 assert!(Command::new("tar").args(["-xzf",&out,"-C",&extracted]).status().unwrap().success());
 let mut after=BTreeMap::new();files(Path::new(&extracted),Path::new(&extracted),&mut after);assert_eq!(original,after);
 json!({"name":name,"sha256":hash(&out),"bytes":fs::metadata(out).unwrap().len(),"roundtrip_files":after.len(),"all_roundtrip_hashes_equal":true})
}
